BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='O') THEN
  RAISE EXCEPTION 'Manager recovery inventory immutability is unavailable';END IF;
 before_surface:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 IF public.static_weekly_digest_text(before_surface) IS DISTINCT FROM '73797c0a1632a2d9f3fb20bb35e96deace7bc8e958bf4461390cba7c786cdf02'
  OR (length(before_surface)-length(replace(before_surface,'  values','')))/length('  values')<>1 THEN
  RAISE EXCEPTION 'Manager canary membership predecessor does not match the integrated source';END IF;
 SELECT * INTO STRICT captured FROM public.custodial_release_authority_restore_inventory
  WHERE object_kind='function' AND object_identity='custodial_release_canary_authority_surface()';
 IF captured.restore_order<>100071 OR captured.definition_sql IS DISTINCT FROM before_surface
  OR captured.definition_sha256 IS DISTINCT FROM '73797c0a1632a2d9f3fb20bb35e96deace7bc8e958bf4461390cba7c786cdf02' THEN RAISE EXCEPTION 'Captured canary predecessor changed';END IF;
 surface_grants:=public.custodial_release_authority_current_grant_definition('custodial_release_canary_authority_surface()');
 IF public.static_weekly_digest_text(surface_grants) IS DISTINCT FROM 'b7d461eda320ec386b55ce3490063e09848a83723999acdd741e83cad0460498' THEN
  RAISE EXCEPTION 'Canary grant source changed';END IF;
 SELECT * INTO STRICT captured FROM public.custodial_release_authority_restore_inventory WHERE object_kind='grant' AND object_identity='custodial_release_canary_authority_surface()';
 IF captured.restore_order<>1000073 OR captured.definition_sha256<>'a843e6ab1177177e039163a3d520b95d6552de8105474a48e390b25302692f48'
  OR public.static_weekly_digest_text(captured.definition_sql)<>captured.definition_sha256
  OR replace(captured.definition_sql,'''public.custodial_release_canary_authority_surface()''','''custodial_release_canary_authority_surface()''') IS DISTINCT FROM surface_grants THEN
  RAISE EXCEPTION 'Canary grant identity correction is not the exact known representation';END IF;
 FOR item IN SELECT * FROM manager_recovery_expected ORDER BY identity LOOP
  oid_value:=to_regprocedure('public.'||item.identity);
  IF oid_value IS NULL OR public.static_weekly_digest_text(pg_get_functiondef(oid_value)) IS DISTINCT FROM item.sha256 THEN
   RAISE EXCEPTION 'Manager function does not match verified source: %',item.identity;END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE p.oid=oid_value AND
    (a.privilege_type<>'EXECUTE' OR (a.is_grantable AND a.grantee<>p.proowner)
     OR (a.grantee<>p.proowner AND coalesce(r.rolname,'PUBLIC')<>'postgres' AND NOT coalesce(r.rolname=ANY(item.roles),false)))) THEN
   RAISE EXCEPTION 'Manager function exposes an undeclared grant: %',item.identity;END IF;
  FOREACH role_name IN ARRAY item.roles LOOP
   IF NOT has_function_privilege(role_name,oid_value,'EXECUTE') THEN RAISE EXCEPTION 'Missing manager execution role: % %',item.identity,role_name;END IF;
  END LOOP;
  IF has_function_privilege('anon',oid_value,'EXECUTE') OR has_function_privilege('authenticated',oid_value,'EXECUTE') THEN
   RAISE EXCEPTION 'Browser manager SQL execution is prohibited';END IF;
  -- These eight function/grant pairs were absent from both the saved main
  -- and full forward source inventory. No existing arbitrary row is adopted.
  IF EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory i
   WHERE i.object_kind IN ('function','grant') AND CASE WHEN i.object_kind IN ('function','grant') AND position('(' IN i.object_identity)>0
    THEN to_regprocedure(i.object_identity) END=oid_value) THEN RAISE EXCEPTION 'Unexpected prior manager recovery capture: %',item.identity;END IF;
  actual:=pg_get_functiondef(oid_value);
  INSERT INTO manager_recovery_targets VALUES('function',item.identity,actual,item.sha256);
  actual:=public.custodial_release_authority_current_grant_definition(item.identity);
  IF actual IS NULL THEN RAISE EXCEPTION 'Manager grant serialization unavailable';END IF;
  INSERT INTO manager_recovery_targets VALUES('grant',item.identity,actual,public.static_weekly_digest_text(actual));
 END LOOP;
 IF (SELECT count(*) FROM manager_recovery_targets)<>16 THEN RAISE EXCEPTION 'Manager recovery target scope changed';END IF;
 FOR item IN SELECT * FROM manager_recovery_identity_corrections LOOP
  SELECT * INTO STRICT captured FROM public.custodial_release_authority_restore_inventory WHERE object_kind=item.kind AND object_identity=item.old_identity;
  IF captured.restore_order<>item.restore_order OR captured.definition_sha256<>item.old_sha256
   OR public.static_weekly_digest_text(captured.definition_sql)<>item.old_sha256
   OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE object_kind=item.kind AND object_identity=item.identity)
   OR public.static_weekly_digest_text(item.definition_sql)<>item.sha256 THEN RAISE EXCEPTION 'Approved-initial recovery spelling predecessor changed: %',item.old_identity;END IF;
  actual:=CASE item.kind WHEN 'function' THEN pg_get_functiondef(('public.'||item.identity)::regprocedure)
   ELSE public.custodial_release_authority_current_grant_definition(item.identity) END;
  IF actual IS DISTINCT FROM item.definition_sql THEN RAISE EXCEPTION 'Approved-initial recovery spelling target changed: %',item.identity;END IF;
 END LOOP;
 after_surface:=replace(before_surface,'  values',E'  values\n'||additions);
 after_surface:=replace(after_surface,'''public.static_weekly_materialize_approved_initial_baseline(uuid,uuid,date,bigint,bigint,text,jsonb)''','''static_weekly_materialize_approved_initial_baseline(uuid,uuid,date,bigint,bigint,text,jsonb)''');
 after_surface:=replace(after_surface,'''public.static_weekly_read_approved_initial_basis(uuid,uuid,date,bigint,text)''','''static_weekly_read_approved_initial_basis(uuid,uuid,date,bigint,text)''');
 after_surface:=replace(after_surface,'''public.static_weekly_read_approved_initial_confirmation(uuid,text)''','''static_weekly_read_approved_initial_confirmation(uuid,text)''');
 after_surface:=replace(after_surface,'''public.static_weekly_register_approved_initial_baseline(uuid,text,jsonb)''','''static_weekly_register_approved_initial_baseline(uuid,text,jsonb)''');
 EXECUTE after_surface;
 after_surface:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 IF public.static_weekly_digest_text(after_surface) IS DISTINCT FROM 'f877d8cacc8090426fb3fef36a2219aa6010ae203a53a7f5def0782a707e77c7'
  OR public.custodial_release_authority_current_grant_definition('custodial_release_canary_authority_surface()') IS DISTINCT FROM surface_grants THEN
  RAISE EXCEPTION 'Manager canary membership differs from the source-derived target';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 FOR item IN SELECT * FROM manager_recovery_identity_corrections LOOP
  UPDATE public.custodial_release_authority_restore_inventory SET object_identity=item.identity,definition_sql=item.definition_sql,definition_sha256=item.sha256,captured_at=statement_timestamp()
   WHERE object_kind=item.kind AND object_identity=item.old_identity AND restore_order=item.restore_order AND definition_sha256=item.old_sha256;
  GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Approved-initial recovery spelling scope changed';END IF;
 END LOOP;
 FOR item IN SELECT * FROM manager_recovery_targets ORDER BY object_kind,object_identity LOOP
  SELECT max(restore_order)+1 INTO next_order FROM public.custodial_release_authority_restore_inventory WHERE object_kind=item.object_kind;
  IF next_order IS NULL THEN RAISE EXCEPTION 'Manager recovery dependency bucket is unavailable';END IF;
  INSERT INTO public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
   VALUES(next_order,item.object_kind,item.object_identity,item.definition_sql,item.definition_sha256);
 END LOOP;
 UPDATE public.custodial_release_authority_restore_inventory SET definition_sql=after_surface,definition_sha256='f877d8cacc8090426fb3fef36a2219aa6010ae203a53a7f5def0782a707e77c7',captured_at=statement_timestamp()
  WHERE object_kind='function' AND object_identity='custodial_release_canary_authority_surface()' AND definition_sql=before_surface AND definition_sha256='73797c0a1632a2d9f3fb20bb35e96deace7bc8e958bf4461390cba7c786cdf02';
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Canary recovery update scope changed';END IF;
 UPDATE public.custodial_release_authority_restore_inventory SET definition_sql=surface_grants,definition_sha256='b7d461eda320ec386b55ce3490063e09848a83723999acdd741e83cad0460498',captured_at=statement_timestamp()
  WHERE object_kind='grant' AND object_identity='custodial_release_canary_authority_surface()' AND definition_sha256='a843e6ab1177177e039163a3d520b95d6552de8105474a48e390b25302692f48';
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Canary grant representation update scope changed';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 IF EXISTS(SELECT 1 FROM manager_recovery_targets t LEFT JOIN public.custodial_release_authority_restore_inventory i USING(object_kind,object_identity)
  WHERE i.definition_sql IS DISTINCT FROM t.definition_sql OR i.definition_sha256 IS DISTINCT FROM t.definition_sha256) THEN
  RAISE EXCEPTION 'Manager recovery readback does not match the exact targets';END IF;
 IF EXISTS(SELECT u.* FROM manager_unrelated_recovery u WHERE NOT(u.object_kind IN ('function','grant') AND u.object_identity='custodial_release_canary_authority_surface()') AND NOT EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c WHERE c.kind=u.object_kind AND c.old_identity=u.object_identity)
   EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT i.* FROM public.custodial_release_authority_restore_inventory i WHERE NOT(i.object_kind IN ('function','grant') AND i.object_identity='custodial_release_canary_authority_surface()')
   AND NOT EXISTS(SELECT 1 FROM manager_recovery_targets t WHERE t.object_kind=i.object_kind AND t.object_identity=i.object_identity)
   AND NOT EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c WHERE c.kind=i.object_kind AND c.identity=i.object_identity)
   EXCEPT SELECT * FROM manager_unrelated_recovery) THEN RAISE EXCEPTION 'Unrelated recovery bindings changed';END IF;
 IF EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c LEFT JOIN public.custodial_release_authority_restore_inventory i ON i.object_kind=c.kind AND i.object_identity=c.identity
  WHERE i.restore_order IS DISTINCT FROM c.restore_order OR i.definition_sql IS DISTINCT FROM c.definition_sql OR i.definition_sha256 IS DISTINCT FROM c.sha256) THEN
  RAISE EXCEPTION 'Approved-initial recovery identities did not converge';END IF;
 IF EXISTS(SELECT 1 FROM manager_recovery_expected e WHERE NOT EXISTS(SELECT 1 FROM public.custodial_release_canary_authority_surface() s WHERE s.object_kind='function' AND s.object_identity=e.identity)
   OR NOT EXISTS(SELECT 1 FROM public.custodial_release_canary_authority_surface() s WHERE s.object_kind='grant' AND s.object_identity=e.identity)) THEN
  RAISE EXCEPTION 'Manager canary surface is incomplete';END IF;
 IF (SELECT max(restore_order) FROM public.custodial_release_authority_restore_inventory i JOIN manager_recovery_targets t USING(object_kind,object_identity) WHERE i.object_kind='function')
  >=(SELECT min(restore_order) FROM public.custodial_release_authority_restore_inventory i JOIN manager_recovery_targets t USING(object_kind,object_identity) WHERE i.object_kind='grant') THEN
  RAISE EXCEPTION 'Manager recovery functions must be restored before their grants';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='O') THEN RAISE EXCEPTION 'Manager recovery guard was not restored';END IF;
END $bind$;
COMMIT;
